sys_script_fix.script:
gs.info('Quebec: Software Asset Management Foundation - Populates cds_client_name and cds_client_mapping as the last step of SAMS plugin activation.');

function populateCDSNameAndMapping() {
	var script = 'SAMPremiumUtils.executeCDSJob(\'Download Normalized Company Names\');'
    + 'SAMPremiumUtils.executeCDSJob(\'Download Normalized Company Mappings\');';
	GlideRunScriptJob.scheduleScript(script);
}

populateCDSNameAndMapping();
